import { initTRPC } from '@trpc/server';
import { createHTTPServer } from '@trpc/server/adapters/standalone';

// ---------------------------------------------------------------------------
// Context
// ---------------------------------------------------------------------------
function createContext() {
  return {};
}
export type Context = Awaited<ReturnType<typeof createContext>>;

// ---------------------------------------------------------------------------
// Router definition
// ---------------------------------------------------------------------------
const t = initTRPC.context<Context>().create();

const appRouter = t.router({
  /**
   * chatStream – returns an AsyncGenerator that yields three chunks.
   *
   * tRPC v11 detects when a query resolver returns an AsyncGenerator and
   * REDACTEDmatically streams each yielded value to the client over HTTP using
   * a newline-delimited JSON format (compatible with httpBatchStreamLink).
   */
  chatStream: t.procedure.query(async function* () {
    yield 'hello';
    yield 'world';
    yield '!';
  }),
});

export type AppRouter = typeof appRouter;

// ---------------------------------------------------------------------------
// Standalone HTTP server
// ---------------------------------------------------------------------------
createHTTPServer({
  router: appRouter,
  createContext,
}).listen(3000, () => {
  console.log('tRPC server listening on http://localhost:3000');
});

import { createTRPCClient, httpBatchStreamLink } from '@trpc/client';
import type { AppRouter } from './server';

// ---------------------------------------------------------------------------
// tRPC client using httpBatchStreamLink
//
// httpBatchStreamLink is designed to work with server procedures that return
// AsyncGenerators / AsyncIterables.  When the procedure resolves, the link
// returns an AsyncIterable that can be consumed with `for await…of`.
// ---------------------------------------------------------------------------
const trpc = createTRPCClient<AppRouter>({
  links: [
    httpBatchStreamLink({
      url: 'http://localhost:3000',
    }),
  ],
});

async function main() {
  console.log('Calling chatStream…');

  // The query() call resolves to an AsyncIterable<string>
  const iterable = await trpc.chatStream.query();

  for await (const chunk of iterable) {
    console.log('chunk:', chunk);
  }

  console.log('Stream finished.');
}

main().catch((err) => {
  console.error('Client error:', err);
  process.exit(1);
});
